function scopedPath(path:string){if(typeof window==='undefined')return path;const householdId=new URLSearchParams(window.location.search).get('householdId');if(!householdId||!path.startsWith('/api/'))return path;const url=new URL(path,window.location.origin);url.searchParams.set('householdId',householdId);return url.pathname+url.search+url.hash}
async function api(path:string,body?:any,method?:'GET'|'POST'|'DELETE'){return requestJSON(scopedPath(path),body,method)}
