 const [recording,setRecording]=useState(false),[audioFile,setAudioFile]=useState<File|null>(null);const recorder=useRef<MediaRecorder|null>(null);const uploadRef=useRef<HTMLInputElement>(null);
 useEffect(()=>()=>{const active=recorder.current;if(active){active.onstop=null;if(active.state!=='inactive')active.stop();active.stream.getTracks().forEach(track=>track.stop());recorder.current=null}},[]);
 useEffect(()=>{if(page==='ask')return;const active=recorder.current;if(active){active.onstop=null;if(active.state!=='inactive')active.stop();active.stream.getTracks().forEach(track=>track.stop());recorder.current=null;setRecording(false)}},[page]);
 function clearPrivateState(){setAnswer(null);setQuestion('');setCitation(null);setSelectedItem(null);setSelectedSource(null);setSelectedRoom('');setQueryImage(null);setAudioFile(null);setModal('');setTotp(null);setSessions([]);setPasskeys([]);setAdmin(null);setInviteLink('');setToast('');setPage('overview')}
 const activeHousehold=useRef('');
